{
  "competitors": [
    {
      "name": "ServiceTitan",
      "slug": "servicetitan",
      "category": "direct",
      "description": "Full-platform field service management software targeting mid-market and enterprise contractors. Covers scheduling, dispatch, invoicing, CRM, marketing, and reporting. The dominant platform in the category, used by larger HVAC, plumbing, and electrical contractors.",
      "key_differentiators": [
        "Broadest feature set in the category (end-to-end platform)",
        "Strong brand recognition and enterprise sales motion",
        "Large partner and integration ecosystem",
        "Deep reporting and business intelligence capabilities"
      ],
      "why_included": "Market leader and most recognized name in field service management — investors will ask about ServiceTitan first. Primarily targets mid-market/enterprise but also competes for growth-stage SMBs."
    },
    {
      "name": "Jobber",
      "slug": "jobber",
      "category": "direct",
      "description": "Field service management platform focused on SMB home service businesses. Covers quoting, scheduling, dispatching, invoicing, and client management. Known for clean UX and strong SMB focus, serving tradespeople with 1–50 employees.",
      "key_differentiators": [
        "Purpose-built for SMB home service contractors",
        "Strong UX with quick onboarding",
        "Broad vertical coverage (lawn care, cleaning, HVAC, plumbing, etc.)",
        "Mid-range pricing accessible to small businesses"
      ],
      "why_included": "Most direct competitor for Cadence — same SMB buyer, same category, well-funded and well-known. Investors will ask why Cadence beats Jobber."
    },
    {
      "name": "Housecall Pro",
      "slug": "housecall-pro",
      "category": "direct",
      "description": "All-in-one field service management software targeting small home service businesses. Covers scheduling, dispatch, invoicing, payment processing, and customer communication. Known for ease of use and lower price point, popular with owner-operators.",
      "key_differentiators": [
        "Lowest friction onboarding in the category",
        "Integrated payment processing",
        "Strong mobile app for technicians",
        "Consumer-grade UX at SMB price points"
      ],
      "why_included": "Second most direct SMB competitor alongside Jobber. Positioned at the lower end of the SMB market — important to show how Cadence differentiates from both."
    }
  ],
  "candidate_axes": [
    {
      "x_axis": "SMB Fit vs. Enterprise Orientation",
      "y_axis": "Scheduling & Dispatch Intelligence",
      "rationale": "This pair directly captures Cadence's core claim: it is built for SMBs (vs. ServiceTitan's enterprise gravity) AND offers more sophisticated scheduling/dispatch than Jobber or Housecall Pro. Both axes matter to SMB buyers in the purchase decision — 'will this work for my size?' and 'will it actually optimize my dispatch?'"
    },
    {
      "x_axis": "Time to First Value (Onboarding Speed)",
      "y_axis": "Workflow Depth (Scheduling & Dispatch Capability)",
      "rationale": "SMB buyers care intensely about how quickly they can be live and productive. This axis pair separates ServiceTitan (deep but slow to deploy) from Housecall Pro (fast but shallow) and positions where Cadence aims to sit: fast AND capable. Avoids vanity — all three incumbents genuinely spread across both axes."
    },
    {
      "x_axis": "Price Accessibility for SMBs",
      "y_axis": "Dispatch Automation Depth",
      "rationale": "Reveals the affordability-vs-intelligence tradeoff. Housecall Pro wins on price, ServiceTitan on depth, and Jobber sits in the middle. If Cadence offers dispatch automation closer to ServiceTitan's level at a Jobber/HCP price point, this map shows the gap clearly."
    }
  ],
  "deck_competitors_excluded": [],
  "metadata": {"run_id": "20260622T060009Z"}
}

